DO $patch$ DECLARE d text;BEGIN SELECT pg_get_functiondef('private.base_validate(jsonb)'::regprocedure) INTO d;d:=replace(d,'id text;rules jsonb','cursor_id text;rules jsonb');d:=replace(d,'id:=nullif','cursor_id:=nullif');d:=replace(d,'WHILE id IS NOT NULL','WHILE cursor_id IS NOT NULL');d:=replace(d,'IF id=ANY(seen)','IF cursor_id=ANY(seen)');d:=replace(d,'seen:=seen||id','seen:=seen||cursor_id');d:=replace(d,$s$value->>'id'=id$s$,$s$value->>'id'=cursor_id$s$);d:=replace(d,$s$profiles WHERE id::text=r->>'user_id'$s$,$s$profiles p WHERE p.id::text=r->>'user_id'$s$);EXECUTE d;END $patch$;
CREATE OR REPLACE FUNCTION private.base_rules(u uuid,c jsonb) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH RECURSIVE tree AS (SELECT x FROM jsonb_array_elements(c->'units') x WHERE x->>'kind'='block' AND coalesce((x->>'active')::boolean,false) UNION ALL SELECT x FROM jsonb_array_elements(c->'units') x JOIN tree t ON x->>'parent_id'=t.x->>'id' WHERE coalesce((x->>'active')::boolean,false)),member AS (SELECT m FROM jsonb_array_elements(c->'memberships') m WHERE m->>'user_id'=u::text AND private.base_valid_at(m) AND EXISTS(SELECT 1 FROM tree WHERE x->>'id'=m->>'unit_id')),ancestors AS (SELECT x->>'id' id,x->>'parent_id' parent_id FROM tree JOIN member ON x->>'id'=member.m->>'unit_id' UNION SELECT t.x->>'id',t.x->>'parent_id' FROM tree t JOIN ancestors a ON t.x->>'id'=a.parent_id),rules AS (SELECT r||jsonb_build_object('source_kind','direct','source_id',r->>'id') r FROM jsonb_array_elements(c->'grants') r WHERE r->>'user_id'=u::text UNION ALL SELECT r||jsonb_build_object('source_kind','default','source_id',d->>'id','source_name',d->>'name') FROM jsonb_array_elements(c->'defaults') d CROSS JOIN LATERAL jsonb_array_elements(d->'rules') r WHERE private.base_valid_at(d) AND ((d->>'unit_id' IS NOT NULL AND EXISTS(SELECT 1 FROM ancestors WHERE id=d->>'unit_id')) OR (d->>'title_id' IS NOT NULL AND EXISTS(SELECT 1 FROM member WHERE m->>'title_id'=d->>'title_id') AND EXISTS(SELECT 1 FROM jsonb_array_elements(c->'titles') t WHERE t->>'id'=d->>'title_id' AND coalesce((t->>'active')::boolean,false)))) UNION ALL SELECT r||jsonb_build_object('source_kind','bundle','source_id',b->>'id','source_name',b->>'name') FROM jsonb_array_elements(c->'bindings') a JOIN LATERAL jsonb_array_elements(c->'bundles') b ON b->>'id'=a->>'bundle_id' CROSS JOIN LATERAL jsonb_array_elements(b->'rules') r WHERE a->>'user_id'=u::text AND private.base_valid_at(a) AND private.base_valid_at(b)) SELECT coalesce(jsonb_agg(r),'[]'::jsonb) FROM rules WHERE private.base_valid_at(r) $$;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.crm_owner_visible(uuid,uuid,timestamp with time zone)'::regprocedure) INTO d;d:=replace(d,'FUNCTION public.crm_owner_visible(','FUNCTION private.base_crm_owner_legacy(');EXECUTE d;END $$;
CREATE OR REPLACE FUNCTION public.crm_owner_visible(_owner uuid,_department uuid DEFAULT NULL,_at timestamptz DEFAULT now()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN NOT public.biz_admin(auth.uid()) AND private.base_tier1(auth.uid(),'biz.crm_use')='ALLOW' THEN private.is_active(auth.uid()) AND _owner=auth.uid() ELSE private.base_crm_owner_legacy(_owner,_department,_at) END $$;
DO $patch$ DECLARE d text;BEGIN SELECT pg_get_functiondef('private.base_effective(uuid,jsonb)'::regprocedure) INTO d;d:=replace(d,$s$'tier',CASE WHEN privileged THEN 0$s$,$s$'bypass',privileged OR (r.key LIKE 'biz.crm_%' AND public.biz_admin(u)),'tier',CASE WHEN privileged OR (r.key LIKE 'biz.crm_%' AND public.biz_admin(u)) THEN 0$s$);EXECUTE d;END $patch$;
CREATE OR REPLACE FUNCTION private.base_validate_extra(c jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb;k text;BEGIN FOREACH k IN ARRAY ARRAY['defaults','bundles'] LOOP FOR r IN SELECT value FROM jsonb_array_elements(c->k) LOOP IF coalesce(trim(r->>'name'),'')='' OR jsonb_typeof(r->'rules') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Bộ quyền thiếu tên hoặc danh sách quyền.';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(r->'rules') x WHERE jsonb_typeof(x)<>'object' OR coalesce(x->>'id','')='') OR EXISTS(SELECT 1 FROM jsonb_array_elements(r->'rules') x GROUP BY x->>'id' HAVING count(*)>1) THEN RAISE EXCEPTION 'Quyền thành phần thiếu hoặc trùng ID.';END IF;END LOOP;END LOOP;FOR r IN SELECT value FROM jsonb_array_elements(c->'grants') UNION ALL SELECT value FROM jsonb_array_elements(c->'memberships') UNION ALL SELECT value FROM jsonb_array_elements(c->'bindings') UNION ALL SELECT value FROM jsonb_array_elements(c->'defaults') UNION ALL SELECT value FROM jsonb_array_elements(c->'bundles') UNION ALL SELECT q FROM jsonb_array_elements(c->'defaults') b CROSS JOIN LATERAL jsonb_array_elements(b->'rules') q UNION ALL SELECT q FROM jsonb_array_elements(c->'bundles') b CROSS JOIN LATERAL jsonb_array_elements(b->'rules') q LOOP IF nullif(r->>'starts_at','') IS NOT NULL AND nullif(r->>'ends_at','') IS NOT NULL AND (r->>'ends_at')::timestamptz<=(r->>'starts_at')::timestamptz THEN RAISE EXCEPTION 'Thời hạn kết thúc phải sau bắt đầu.';END IF;END LOOP;END $$;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('private.base_validate(jsonb)'::regprocedure) INTO d;d:=replace(d,'rules:=coalesce','PERFORM private.base_validate_extra(c);rules:=coalesce');EXECUTE d;END $$;
REVOKE ALL ON FUNCTION private.base_crm_owner_legacy(uuid,uuid,timestamptz),private.base_validate_extra(jsonb) FROM PUBLIC,anon,authenticated;